import heapq

def shortest_path(edges, start, end):
    # エッジの重みにマイナスが含まれているかチェック
    for u, v, w in edges:
        if w < 0:
            raise ValueError("Edges with negative weights are not allowed.")

    # start と end が同じ場合の処理
    if start == end:
        return (0, [start])

    # グラフの構築 (隣接リスト)
    graph = {}
    for u, v, w in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, w))
        # グラフに存在しないto_nodeもキーとして登録しておく（空のリスト）
        if v not in graph:
            graph[v] = []

    # start や end がグラフのノードに含まれていない場合の対策
    if start not in graph or end not in graph:
        return (None, None)

    # ダイクストラ法の実装
    # 優先度付きキューには (現在の総距離, 現在のノード, 経路のリスト) を格納
    queue = [(0, start, [start])]

    # 訪問済みのノードを記録する辞書（最短距離を格納）
    distances = {start: 0}

    while queue:
        current_distance, current_node, path = heapq.heappop(queue)

        # 目的地に到達した場合
        if current_node == end:
            return (current_distance, path)

        # すでに記録された最短距離よりも長い場合はスキップ
        if current_distance > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            # より短い経路が見つかった場合
            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor, path + [neighbor]))

    # 経路が存在しない場合
    return (None, None)

# --- 使用例 ---
if __name__ == "__main__":
    edges = [("A", "B", 1), ("B", "C", 2), ("A", "C", 5)]
    print(shortest_path(edges, "A", "C"))  # 出力: (3, ['A', 'B', 'C'])

    print(shortest_path(edges, "A", "A"))  # 出力: (0, ['A'])

    print(shortest_path(edges, "C", "A"))  # 出力: (None, None)

    try:
        shortest_path([("A", "B", -1)], "A", "B")
    except ValueError as e:
        print(e)  # 出力: Edges with negative weights are not allowed.
